import{_ as e,o as r,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"🔬 科学快报 | 2026年7月18日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-18.md","filePath":"science-log/src/reconstructed/2026-07-18.md"}'),n={name:"science-log/src/reconstructed/2026-07-18.md"};function s(i,a,l,h,g,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="🔬-科学快报-2026年7月18日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月18日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月18日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月18日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-07 取数说明：2026-07-18 为周六，Nature/Science/PNAS 当日<strong>无新出版条目</strong>（CrossRef 精确日期命中 0 条），故科学前沿取最近一个出版窗口 <strong>2026-07-15 ~ 2026-07-17</strong> 的真实条目；AI 前沿严格取 arXiv cs.AI 当日（20260718）投递。</p></blockquote><hr><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧲-扭转菱面石墨烯里的「分数高陈绝缘体」c-7-3" tabindex="-1">🧲 扭转菱面石墨烯里的「分数高陈绝缘体」C = 7/3 <a class="header-anchor" href="#🧲-扭转菱面石墨烯里的「分数高陈绝缘体」c-7-3" aria-label="Permalink to &quot;🧲 扭转菱面石墨烯里的「分数高陈绝缘体」C = 7/3&quot;">​</a></h3><p><strong>Fractional high-Chern insulator in twisted rhombohedral graphene</strong><em>Nature 655, 892–898 (2026)</em></p><p>Zexu Li、Wenxuan Wang 等（含 hBN 晶体供应商 Watanabe、Taniguchi，理论合作者 X. C. Xie）在「Bernal 双层石墨烯 + 菱面体四层石墨烯」构成的莫尔平坦带体系中，于填充因子 ν = 1 及 ν = 3 附近观测到陈数从 |C| = 1 一路到 |C| = 7 的量子反常霍尔绝缘体序列——零磁场下的陈绝缘体家族被一次扩到前所未有的宽度。更关键的是在 ν = 2/3 处出现 C = 7/3 的分数陈绝缘体，这个分数<strong>既不属于 Jain 序列，也不在现有高陈数理论预言之内</strong>。它意味着分数量子霍尔物理的「朗道能级语言」之外还有新的组织方式，为无磁场下的任意子与容错拓扑量子计算提供了莫尔平台。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10762-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10762-7</a></p><h3 id="🧬-给细胞装一个-α-酮戊二酸「核内探针」-找出线粒体→染色质的供给线路" tabindex="-1">🧬 给细胞装一个 α-酮戊二酸「核内探针」，找出线粒体→染色质的供给线路 <a class="header-anchor" href="#🧬-给细胞装一个-α-酮戊二酸「核内探针」-找出线粒体→染色质的供给线路" aria-label="Permalink to &quot;🧬 给细胞装一个 α-酮戊二酸「核内探针」，找出线粒体→染色质的供给线路&quot;">​</a></h3><p><strong>A transcriptional biosensor reveals mechanisms of α-ketoglutarate signaling to chromatin</strong><em>Science 393 (2026)</em></p><p>αKG 是染色质去甲基化反应的必需底物，但细胞核内这个代谢池由谁供给一直不清楚。UT Southwestern 儿童医学研究所 Alex C. Sternisha 等（34 人合作）把蓝藻的 αKG 响应转录因子 NtcA 改造成荧光生物传感器，直接读到人细胞核内 αKG 浓度，并据此做基因筛选。他们定义出一条跨细胞器通路：线粒体内的 GPT2（谷丙转氨酶 2）与 SLC25A11 转运体<strong>顺序接力</strong>，把 αKG 送进核内。在 GPT2 缺陷（一种先天性代谢病）小鼠模型中，Gpt2 缺失导致脑内组蛋白超甲基化、神经发育基因失调，补充 αKG 可以逆转这些改变并改善小鼠体能——把一个「代谢物浓度」问题变成了可干预的病理机制。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adx8675" target="_blank" rel="noreferrer">10.1126/science.adx8675</a></p><h3 id="🧠-皮层编码并不「分类」-而是靠多样性换取可分性" tabindex="-1">🧠 皮层编码并不「分类」，而是靠多样性换取可分性 <a class="header-anchor" href="#🧠-皮层编码并不「分类」-而是靠多样性换取可分性" aria-label="Permalink to &quot;🧠 皮层编码并不「分类」，而是靠多样性换取可分性&quot;">​</a></h3><p><strong>Rarely categorical, highly separable representations along the cortical hierarchy</strong><em>Nature (2026)</em></p><p>Posani、Wang、Muscinelli、Paninski、Fusi 用国际脑实验室（IBL）公开的全脑图谱数据集，系统分析了 43 个皮层区域、14,000 多个单元在复杂任务中对认知、感觉与运动变量的编码方式。结论是<strong>尺度依赖</strong>的：在整个皮层尺度上，神经选择性确实呈分类结构，且区域间的组织与解剖连接相呼应；但一旦进入单个区域内部，分类表征就变得稀少、只集中在初级感觉区，绝大多数神经元响应高度混杂。作者用理论加实证说明：这种多样性正好撑起高维表征，从而带来<strong>最大可分性</strong>——线性读出可以沿任意方向把实验条件分开。若按各区域实际编码的信息量归一，所有皮层区域都达到可分性上限。皮层的策略不是「一类细胞一个变量」，而是「用噪声般的多样性换读出自由度」。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10668-4" target="_blank" rel="noreferrer">10.1038/s41586-026-10668-4</a></p><h3 id="🔊-左听觉皮层的-α-节律-决定了你能听懂多快的话" tabindex="-1">🔊 左听觉皮层的 α 节律，决定了你能听懂多快的话 <a class="header-anchor" href="#🔊-左听觉皮层的-α-节律-决定了你能听懂多快的话" aria-label="Permalink to &quot;🔊 左听觉皮层的 α 节律，决定了你能听懂多快的话&quot;">​</a></h3><p><strong>Alpha rhythms in the left auditory cortex set the speed limit for speech comprehension</strong><em>PNAS 123 (2026)</em></p><p>人理解言语有速度上限：语速一超过约每秒 10 个音节，理解率就断崖式下降，但机制不明。北京航空航天大学 Yayue Gao 等（17 人）把心理物理测量、头皮脑电、经颅交流电刺激（tACS）、节律性感觉刺激与颅内立体脑电（sEEG）合在一套实验里，发现<strong>个体 α 频率（IAF）可以精确预测</strong>每个人能听懂的最快语速。因果性证据来自干预：用高精度 tACS 与节律听觉刺激加速内源 α 节律后，受试者能听懂更快的语音。sEEG 进一步定位到左听觉皮层——该处 α 活动越快，神经响应对语音包络的夹带（entrainment）越强。这把「认知处理速度上限」从抽象描述落到了一个可测量、可外部调制的振荡器参数上。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2601610123" target="_blank" rel="noreferrer">10.1073/pnas.2601610123</a></p><h3 id="⛏️-海山俯冲-特富金矿的「三步投料」机制" tabindex="-1">⛏️ 海山俯冲：特富金矿的「三步投料」机制 <a class="header-anchor" href="#⛏️-海山俯冲-特富金矿的「三步投料」机制" aria-label="Permalink to &quot;⛏️ 海山俯冲：特富金矿的「三步投料」机制&quot;">​</a></h3><p><strong>Seamount subduction drives bonanza-grade gold mineralization</strong><em>Science Advances 12 (2026)</em></p><p>巨型金矿几乎都与造山带相关，但因果链一直模糊。中科院地质与地球物理研究所刘艳红、万博等（合作者含 Ross N. Mitchell、Wenjiao Xiao、Thomas M. Gernon）用超低检出限方法测定了增生杂岩中不同变质程度镁铁质岩石的金含量，发现两个规律：地幔柱改造过的样品金含量更高，而变质程度升高时金含量下降（金被释放出去）。据此提出三步模型：(i) 地幔柱把金从深部地幔泵入大洋地壳中的海山；(ii) 海山链俯冲时金被释放并储存在上覆板块底部；(iii) 岩浆爆发期的熔体/流体活动把金搬运到浅部成矿。该模型还能解释过去 6 亿年金矿出现频率与已知俯冲海山之间的显著对应。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aef6613" target="_blank" rel="noreferrer">10.1126/sciadv.aef6613</a></p><hr><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎯-把因果模仿学习推到长程连续控制-causal-sqil-causal-iq-learn" tabindex="-1">🎯 把因果模仿学习推到长程连续控制：Causal SQIL / Causal IQ-Learn <a class="header-anchor" href="#🎯-把因果模仿学习推到长程连续控制-causal-sqil-causal-iq-learn" aria-label="Permalink to &quot;🎯 把因果模仿学习推到长程连续控制：Causal SQIL / Causal IQ-Learn&quot;">​</a></h3><p><strong>Scalable Causal Imitation Learning</strong><em>arXiv (2026)</em></p><p>Eylam Tagor、Mingxuan Li、Elias Bareinboim 指出，模仿学习的软肋是「模仿者与专家的观测不一致」且专家示范里存在未观测混杂因子；因果模仿学习（CIL）虽能靠序列 π-backdoor 准则找调整集，但已有的 Causal BC 与 Causal GAIL 只适合短程、低维设定——前者累积误差爆炸，后者不稳定且样本效率差，而且在连续控制上序列 π-backdoor 调整本身就算不动。作者的解法是保留因果调整框架、换掉模仿目标：提出 Causal Soft Q Imitation Learning（Causal SQIL）与 Causal Inverse soft-Q Learning（Causal IQ-Learn），两者都作用在「经因果调整后的状态表示」上，并用一个高效近似把全时程调整压缩成<strong>固定大小的滑动窗口</strong>。在一批带混杂的连续控制环境里，二者显著超过既有 CIL 方法、长程任务上有时甚至超过专家，而所有「不懂因果」的模仿方法都学不到有意义的策略。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.17003" target="_blank" rel="noreferrer">2607.17003</a></p><h3 id="🎲-反事实-shapley-把「技能」与「运气」分开记功" tabindex="-1">🎲 反事实 Shapley：把「技能」与「运气」分开记功 <a class="header-anchor" href="#🎲-反事实-shapley-把「技能」与「运气」分开记功" aria-label="Permalink to &quot;🎲 反事实 Shapley：把「技能」与「运气」分开记功&quot;">​</a></h3><p><strong>Counterfactual Shapley Credit Assignment</strong><em>arXiv (2026)</em></p><p>信用分配是强化学习的核心难题：现有做法要么靠时间邻近性，要么靠事后条件化的奖励重加权，往往分不清一次成功究竟来自<strong>策略（技能）<strong>还是</strong>环境随机性（运气）</strong>。Mingxuan Li、Kai-Zhan Lee、Elias Bareinboim 提出 Counterfactual Shapley Credit Assignment，用因果理论下的「反事实 Shapley 值」（φ 值）来分配功劳与责任：通过重新分配环境奖励，φ 值在三个维度上改善时序信用分配——稀疏因果、高随机性、延迟奖励，同时<strong>保持最优策略不变</strong>。他们给出了一致估计量以高效计算 φ 值，并据此构造新的策略梯度方法 φ-PPO，配 Prioritized Trajectory Replay。实验显示 φ 值能精确对齐任务奖励的真实原因，在先前 SOTA 无法收敛的困难环境里样本效率明显更优。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.16999" target="_blank" rel="noreferrer">2607.16999</a></p><h3 id="🌡️-期望自由能就是-ρ-pomdp-的信念相关效用-探索权重不需要调" tabindex="-1">🌡️ 期望自由能就是 ρ-POMDP 的信念相关效用：探索权重不需要调 <a class="header-anchor" href="#🌡️-期望自由能就是-ρ-pomdp-的信念相关效用-探索权重不需要调" aria-label="Permalink to &quot;🌡️ 期望自由能就是 ρ-POMDP 的信念相关效用：探索权重不需要调&quot;">​</a></h3><p><strong>Expected Free Energy as Belief-Dependent Utility for rho-POMDPs</strong><em>arXiv (2026)</em></p><p>部分可观测下的智能体必须决定「何时值得花代价去看」。标准 POMDP 只通过最终奖励给信息定价；ρ-POMDP 直接用信念相关效用 ρ 奖励不确定性下降，但 ρ 的形式与权重在每个任务上都要手调。Patrick Cooper、Alvaro Velasquez 证明：<strong>最小化期望自由能（EFE）精确等价于</strong>求解一个效用为期望信息增益的 ρ-POMDP，而且探索权重被固定为 w = 1——因为变分界把实用价值与认知价值放进同一单位（nat）。他们在 observe-then-commit 型 POMDP 上完成证明，并推广到因子化观测 POMDP（涵盖「观测不改变隐状态」的交错观察—行动问题，如无损检测与移动传感）。Tiger、RockSample 与一个 65,000+ 状态的结构检测基准上，未调参的权重持平或超过同视界的纯奖励规划，避免了逐任务调 bonus 造成的过度探索。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.16981" target="_blank" rel="noreferrer">2607.16981</a></p><h3 id="🧵-连续思维链的两种监督方式-在长推理上一起失灵" tabindex="-1">🧵 连续思维链的两种监督方式，在长推理上一起失灵 <a class="header-anchor" href="#🧵-连续思维链的两种监督方式-在长推理上一起失灵" aria-label="Permalink to &quot;🧵 连续思维链的两种监督方式，在长推理上一起失灵&quot;">​</a></h3><p><strong>Training Continuous Chain of Thought Models: A Tale of Two Regimes</strong><em>arXiv (2026)</em></p><p>连续思维链（continuous CoT）用一小串稠密潜向量替代冗长的文字推理轨迹。早期方法用<strong>间接监督</strong>：让潜在表示的最终状态去匹配完整文字轨迹，因此训练时必须自回归地慢速生成；已有的一种直接监督则去拟合压缩后 token 的分布。Varun Yerram、He He、Eunsol Choi 提出 C-MTP：把每个潜向量直接建模为待压缩 CoT 片段内<strong>词嵌入的平均</strong>——更简单、更快。在既有的简化 CoT 评测（&lt; 100 token）上，C-MTP 优于先前的直接监督方法、与更慢的间接监督方法竞争力相当。作者随后把评测扩展到推理轨迹长达数百 token 的复杂任务，结果两类训练方式都<strong>大幅退化（约 65% 性能下降）</strong>——这暴露了当前连续 CoT 方法的能力边界，而不只是一次调参问题。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.16972" target="_blank" rel="noreferrer">2607.16972</a></p><h3 id="🪨-lomekwi-把「工具发现」从「工具使用」里拆出来-并发现逆向缩放" tabindex="-1">🪨 Lomekwi：把「工具发现」从「工具使用」里拆出来，并发现逆向缩放 <a class="header-anchor" href="#🪨-lomekwi-把「工具发现」从「工具使用」里拆出来-并发现逆向缩放" aria-label="Permalink to &quot;🪨 Lomekwi：把「工具发现」从「工具使用」里拆出来，并发现逆向缩放&quot;">​</a></h3><p><strong>Lomekwi: Resource-Bounded Tool Discovery in LLM Agents</strong><em>arXiv (2026)</em></p><p>现有工具使用基准对复杂的多步任务只报一个成功率，把两件不同的事混成一件。Roshan Klein-Seetharaman、Daniel Wang、Andrew Xu 受认知科学启发，把「工具发现」分解为三个可分别测量的能力：<strong>好奇心</strong>（找到造工具所需部件的能力）、<strong>识别</strong>（发现造工具流程的能力）、<strong>效率</strong>（造好之后用得好的能力），并说明这套框架可以用于既有发现类任务（如 Voyager）。他们的核心发现带反直觉色彩：<strong>识别能力与模型规模呈逆向缩放</strong>，并用一类组合博弈给出了机理性演示；在另一个模仿真实任务的独立环境里也观察到同样的逆向缩放。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.16961" target="_blank" rel="noreferrer">2607.16961</a></p><hr><blockquote><p>📅 日期：2026-07-18 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',48)])])}const d=e(n,[["render",s]]);export{u as __pageData,d as default};
